// === Tab: mySketch ===
class Particle {
  constructor(x, y, r, c) {
    this.position = new p5.Vector(x, y);
    this.velocity = p5.Vector.random2D();
    this.velocity.mult(3);
    this.r = r;
		this.c = c;
    this.m = r * 0.1;
		this.coloredFrames = 0;
  }

  update() {
    this.position.add(this.velocity);
  }


  checkBoundaryCollision() {
    if (this.position.x > width - this.r) {
      this.position.x = width - this.r;
      this.velocity.x *= -1;
    } else if (this.position.x < this.r) {
      this.position.x = this.r;
      this.velocity.x *= -1;
    } else if (this.position.y > height - this.r) {
      this.position.y = height - this.r;
      this.velocity.y *= -1;
    } else if (this.position.y < this.r) {
      this.position.y = this.r;
      this.velocity.y *= -1;
    }
  }

	intersects(other) {
		let distanceVect = p5.Vector.sub(other.position, this.position);

    // Calculate magnitude of the vector separating the balls
    let distanceVectMag = distanceVect.mag();

    // Minimum distance before they are touching
    let minDistance = this.r + other.r;

    return distanceVectMag <= minDistance;
	}

  checkCollision(other) {
		var distanceVect = p5.Vector.sub(other.position, this.position);

    // Calculate magnitude of the vector separating the balls
    var distanceVectMag = distanceVect.mag();

    // Minimum distance before they are touching
    var minDistance = this.r + other.r;

    if (distanceVectMag < minDistance) {
			var distanceVect = p5.Vector.sub(other.position, this.position);
    	var distanceVectMag = distanceVect.mag();
    	var minDistance = this.r + other.r;
      let distanceCorrection = (minDistance - distanceVectMag) / 2.0;
      let d = distanceVect.copy();
      let correctionVector = d.normalize().mult(distanceCorrection);
      other.position.add(correctionVector);
      this.position.sub(correctionVector);

      // get angle of distanceVect
      let theta = distanceVect.heading();
      // precalculate trig values
      let sine = sin(theta);
      let cosine = cos(theta);

      /* bTemp will hold rotated ball this.positions. You 
       just need to worry about bTemp[1] this.position*/
      let bTemp = [new p5.Vector(), new p5.Vector()];

      /* this ball's this.position is relative to the other
       so you can use the vector between them (bVect) as the 
       reference point in the rotation expressions.
       bTemp[0].this.position.x and bTemp[0].this.position.y will initialize
       automatically to 0.0, which is what you want
       since b[1] will rotate around b[0] */
      bTemp[1].x = cosine * distanceVect.x + sine * distanceVect.y;
      bTemp[1].y = cosine * distanceVect.y - sine * distanceVect.x;

      // rotate Temporary velocities
      let vTemp = [new p5.Vector(), new p5.Vector()];

      vTemp[0].x = cosine * this.velocity.x + sine * this.velocity.y;
      vTemp[0].y = cosine * this.velocity.y - sine * this.velocity.x;
      vTemp[1].x = cosine * other.velocity.x + sine * other.velocity.y;
      vTemp[1].y = cosine * other.velocity.y - sine * other.velocity.x;

      /* Now that velocities are rotated, you can use 1D
       conservation of momentum equations to calculate 
       the final this.velocity along the x-axis. */
      let vFinal = [new p5.Vector(), new p5.Vector()];

      // final rotated this.velocity for b[0]
      vFinal[0].x =
        ((this.m - other.m) * vTemp[0].x + 2 * other.m * vTemp[1].x) /
        (this.m + other.m);
      vFinal[0].y = vTemp[0].y;

      // final rotated this.velocity for b[0]
      vFinal[1].x =
        ((other.m - this.m) * vTemp[1].x + 2 * this.m * vTemp[0].x) /
        (this.m + other.m);
      vFinal[1].y = vTemp[1].y;

      // hack to avoid clumping
      bTemp[0].x += vFinal[0].x;
      bTemp[1].x += vFinal[1].x;

      /* Rotate ball this.positions and velocities back
       Reverse signs in trig expressions to rotate 
       in the opposite direction */
      // rotate balls
      let bFinal = [new p5.Vector(), new p5.Vector()];

      bFinal[0].x = cosine * bTemp[0].x - sine * bTemp[0].y;
      bFinal[0].y = cosine * bTemp[0].y + sine * bTemp[0].x;
      bFinal[1].x = cosine * bTemp[1].x - sine * bTemp[1].y;
      bFinal[1].y = cosine * bTemp[1].y + sine * bTemp[1].x;

      // update balls to screen this.position
      other.position.x = this.position.x + bFinal[1].x;
      other.position.y = this.position.y + bFinal[1].y;

      this.position.add(bFinal[0]);

      // update velocities
      this.velocity.x = cosine * vFinal[0].x - sine * vFinal[0].y;
      this.velocity.y = cosine * vFinal[0].y + sine * vFinal[0].x;
      other.velocity.x = cosine * vFinal[1].x - sine * vFinal[1].y;
      other.velocity.y = cosine * vFinal[1].y + sine * vFinal[1].x;

			this.coloredFrames = 30;
			return true;
    }
		return false;
  }

  display() {
		if (this.coloredFrames > 0 && this.coloredFrames % 5 < 3) {
			fill(this.c);
			this.coloredFrames--;
		} else {
			noStroke();
    	fill(204);
		}
    ellipse(this.position.x, this.position.y, this.r * 2, this.r * 2);
  }
}

const count = 20;
const particles = [];
let slider;


let osc, envelope;
let scaleArray = [60, 62, 64, 65, 67, 69, 71, 72];
let note = 0;
const minRadius = 10;
const maxRadius = 50;


function setup() {
  createCanvas(1000, 1000);
	osc = new p5.TriOsc();

  // Instantiate the envelope
  envelope = new p5.Env();

  // set attackTime, decayTime, sustainRatio, releaseTime
  envelope.setADSR(0.001, 0.5, 0.1, 0.5);

  // set attackLevel, releaseLevel
  envelope.setRange(1, 0);

  osc.start();
	slider = createSlider(2, 100);

}

function createRandomParticle() {
	const x = random(width);
	const y = random(height);
	const r = random(maxRadius) + minRadius;
	const c = color(random(255), random(255), random(255));
	return new Particle(x, y, r, c);
}

function checkParticles() {
	while (particles.length - slider.value() < 0) {
		const p = createRandomParticle();
		let valid = true;
		for (let i = 0; i < particles.length && valid; i++) {
			if (p.intersects(particles[i])) {
				valid = false;
			}
		}
		if (valid) {
			particles.push(p);
		}
	}

	while (particles.length - slider.value() < 0) {
		particles.splice(-1, 1);
	}
}

function draw() {
  background(22);
	checkParticles();
  for (let i = 0; i < particles.length; i++) {
    var p = particles[i];
    p.update();
    p.display();
    p.checkBoundaryCollision();
		for (let j = 0; j < particles.length; j++) {
			if (i != j)
			  if (particles[i].checkCollision(particles[j])) {
					note = int(map(particles[i].r, minRadius, maxRadius, 0, scaleArray.length - 1));
					let midiValue = scaleArray[note];
					let freqValue = midiToFreq(midiValue);
					osc.freq(freqValue);

					//envelope.play(osc, 0, 0.1);
					envelope.ramp(osc, 0, 1.0, 0);
				};
		}
  }
}

